interface AdminPanelProps {
  isOpen: boolean;
  onClose: () => void;
  onUpdateHero: (mediaType: 'image' | 'video', src: string) => void;
  activeOffer: BoostOfferConfig;
  onUpdateOffer: (config: BoostOfferConfig) => void;
