const AdminPanel: React.FC<AdminPanelProps> = ({ isOpen, onClose, onUpdateHero, activeOffer, onUpdateOffer }) => {
  const [activeTab, setActiveTab] = useState<'upload' | 'generate' | 'offers'>('offers');
